    step("类路径资源在 jar 里时。目录里的 ClassPathResource(conf/a.txt) 能 getFile() 得到 out/conf/a.txt。jar 里的资源(AutoConfiguration.imports)URL 前缀是 jar,isFile() 是 false,getFile() 抛 FileNotFoundException:cannot be resolved to absolute file path because it does not reside in the file system;getInputStream() 正常;contentLength 是 921,lastModified 大于 0,getFilename 是 org.springframework.boot.autoconfigure.AutoConfiguration.imports。读 classpath 资源要用 getInputStream(),别用 getFile()。", t=tl(S(3)), mark=lidx(S(3), 'jar 里的资源 URL 前缀'), done=lidx(S(3), 'ClassPathResource(conf/a.txt) getFile()', 'contentLength'), b=bars([['目录里的资源 getFile()', 1, '成功'], ['jar 里的资源 getFile()', 0, 'FileNotFoundException'], ['jar 里的资源 getInputStream()', 1, '成功'], ['jar 里的资源 contentLength', 921, '921']], 921, done=[0, 2], mark=[1], cur=[3]), kv=KV([['目录里', 'getFile() 可用'], ['jar 里', 'isFile() = false,getFile() 失败'], ['稳妥的读法', 'getInputStream()'], ['jar 里仍可读', 'contentLength、getFilename 都可用']], ['稳妥的读法'])),
